var i=`0771-luwombo`;var n=`world-0771`;var t=`UG`;var s=`eastern-africa`;var o=4;var l=133;var r={en:`Luwombo`,ua:`Лувомбо`};var g={en:`Luwombo is a Uganda classic prepared with yellow onion, tomato, garlic, chicken thigh. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Лувомбо, страва кухні країни Уганда зі складниками: жовта цибуля, помідор, часник, куряче стегно. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,190,`g`],[`tomato`,320,`g`],[`garlic`,4,`clove`],[`ghee`,45,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:12,i:[[`chicken-thigh`,800,`g`],[`carrot`,230,`g`],[`green-bell-pepper`,180,`g`],[`banana-leaf`,6,`leaf`]]},{en:`Wrap chicken and vegetables in clean food-safe banana leaves to form sealed parcels that will hold their sauce.`,ua:`Загорніть курку та овочі в чисте безпечне бананове листя так, щоб згортки втримували підливу.`,t:[`rolling-stuffed-food`],m:10,i:[]},{en:`Steam the sealed parcels over gently boiling water until the chicken is thoroughly cooked and tender.`,ua:`Готуйте щільно закриті згортки на парі над слабко киплячою водою до повної готовності й м’якості курки.`,t:[`banana-leaf-steaming`],m:95,i:[[`water`,700,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`]]}];var d={slug:i,id:n,country:`UG`,region:s,servings:4,minutes:133,title:r,text:g,steps:h};export{t as country,d as default,n as id,l as minutes,s as region,o as servings,i as slug,h as steps,g as text,r as title};